<?php
/** RD-17 WP1A UI: compact existing profile action. Owner CLI only, cwd=public_html, staged outside webroot.
 * No DB writes. Backup: cwd/_patch_backups/RD-17-WP1A-UI_profile-action_20261026-<UTC>-<nonce>/.
 * Rollback: same reviewed file --rollback=<exact receipt backup>; all targets and
 * backup hashes preflighted before any restore/delete. Cache cleanup is external.
 */
const RD16_ID = 'RD-17-WP1A-UI_profile-action_20261026';
const RD16_CACHE = '/home2/boosters/ocartdata/storage/cache/template/';
ini_set('display_errors','0');
ini_set('log_errors','0');
set_error_handler(static function () { throw new RuntimeException('io_or_runtime_warning'); });

function rd16_fail(string $code): void { throw new RuntimeException($code); }
function rd16_json(string $encoded): array {
    $value = json_decode(base64_decode($encoded, true), true);
    if (!is_array($value)) rd16_fail('embedded_contract_invalid');
    return $value;
}
function rd16_targets(): array { return rd16_json(''); }
function rd16_dependencies(): array { return rd16_json(''); }
function rd16_state(string $path): string {
    if (is_link($path)) rd16_fail('linked_file');
    if (!file_exists($path)) return 'absent';
    if (!is_file($path)) rd16_fail('not_regular_file');
    $hash = hash_file('sha256', $path);
    if (!is_string($hash)) rd16_fail('hash_failed');
    return $hash;
}
function rd16_walk(string $root, string $relative): string {
    if (!preg_match('~^[A-Za-z0-9_./-]+$~D', $relative) || in_array('..', explode('/', $relative), true)) rd16_fail('unsafe_relative_path');
    $path = $root;
    foreach (explode('/', $relative) as $part) {
        $path .= '/' . $part;
        if (is_link($path)) rd16_fail('linked_path_component');
    }
    return $path;
}
function rd16_lint(string $path): void {
    if (substr($path, -4) !== '.php') return;
    $lines = []; $status = 1;
    exec(escapeshellarg(PHP_BINARY) . ' -l ' . escapeshellarg($path) . ' 2>&1', $lines, $status);
    if ($status !== 0) rd16_fail('php_lint_failed');
}
function rd16_write_new(string $path, string $body, int $mode = 0600): void {
    $stream = fopen($path, 'xb');
    if (!$stream) rd16_fail('exclusive_create_failed');
    try {
        $offset = 0; $size = strlen($body);
        while ($offset < $size) {
            $written = fwrite($stream, substr($body, $offset));
            if (!$written) rd16_fail('write_failed');
            $offset += $written;
        }
        if (!fflush($stream)) rd16_fail('flush_failed');
    } finally { fclose($stream); }
    if (!chmod($path, $mode)) rd16_fail('chmod_failed');
}
function rd16_permissions(string $path, array $row): void {
    if (!chmod($path, $row['mode'])) rd16_fail('restore_mode_failed');
    if (PHP_OS_FAMILY !== 'Windows') {
        if ($row['uid'] !== null && fileowner($path) !== $row['uid'] && !chown($path, $row['uid'])) rd16_fail('restore_owner_failed');
        if ($row['gid'] !== null && filegroup($path) !== $row['gid'] && !chgrp($path, $row['gid'])) rd16_fail('restore_group_failed');
    }
}

function rd16_hook_templates(string $root, array $rows, ?string $modification = null): void {
    $root=str_replace('\\','/',$root);
    if (count($rows)>1024) rd16_fail('hook_theme_settings_cap');
    $stores=[0=>[]];
    foreach ($rows as $row) {
        if (count($row)!==4 || (!is_string($row[0]) && !is_int($row[0])) || (string)(int)$row[0] !== (string)$row[0] || (int)$row[0]<0 || (int)$row[0]>2147483647) rd16_fail('hook_theme_store_invalid');
        [$store,$key,$value,$serialized]=$row; $store=(int)$store;
        if ((string)$serialized!=='0') rd16_fail('serialized_hook_theme_setting');
        if (!in_array($key,['config_theme','theme_default_directory'],true) || (!is_string($value) && $value!==null) || strlen((string)$value)>256) rd16_fail('hook_theme_setting_invalid');
        if (isset($stores[$store]) && array_key_exists($key,$stores[$store])) rd16_fail('duplicate_hook_theme_setting');
        $stores[$store][$key]=(string)$value;
    }
    foreach ($stores as $values) {
        $effective=array_replace($stores[0],$values);
        $theme=($effective['config_theme']??'')==='default'?($effective['theme_default_directory']??''):($effective['config_theme']??'');
        if (!preg_match('/^[A-Za-z0-9_-]{0,64}$/D',$theme)) rd16_fail('unsafe_hook_theme_segment');
        // Mirror vendor lookup exactly, with store-N values overlaid on store0.
        $base='catalog/view/template/';
        foreach (array_unique([$base.($theme===''?'':$theme.'/').'template/',$base.'default/template/',$base]) as $prefix) {
            foreach (['checkout/checkout.twig','checkout/register.twig','checkout/shipping_address.twig','checkout/payment_address.twig','common/header.twig'] as $view) {
                $path=rd16_walk($root,$prefix.$view);
                if ($modification!==null && strpos($path,str_replace('\\','/',$modification))===0) rd16_fail('hook_modification_redirect');
                if ($prefix!==$base && rd16_state($path)!=='absent') rd16_fail('alternate_hook_template');
            }
        }
    }
}

/** Read-only adapter for the pinned profile registry constructor, metadata only. */
final class Rd17ProfileMetadataDb {
    private $db;
    public function __construct($db) { $this->db=$db; }
    public function query(string $sql) {
        if (strpos($sql,'SELECT ')!==0 || !preg_match('/ FROM `' . preg_quote(DB_PREFIX,'/') . '(setting|custom_field|custom_field_description|custom_field_customer_group)`/', $sql)) rd16_fail('profile_metadata_query_not_allowlisted');
        $q=$this->db->query($sql); if (!$q) rd16_fail('profile_metadata_unavailable');
        $rows=[];
        while ($row=$q->fetch_assoc()) { if (count($rows)>=128) rd16_fail('profile_metadata_cap'); $rows[]=$row; }
        $q->free();
        return (object)['rows'=>$rows,'row'=>$rows[0]??[],'num_rows'=>count($rows)];
    }
}
function rd17_event_relevant(string $pattern): bool {
    do { $previous=$pattern; $pattern=preg_replace('~^(?:catalog|system)(?:/|$)~','',$pattern); } while ($previous!==$pattern);
    foreach (rd16_json('') as $target) if (fnmatch($pattern,$target) || fnmatch($pattern.'*',$target)) return true;
    return false;
}
function rd17_events_normalize(array $events): string {
    $rows=[];
    foreach ($events as $event) {
        if ((int)$event['status']!==1 || !rd17_event_relevant((string)$event['trigger'])) continue;
        $rows[]=[(string)$event['code'],(string)$event['trigger'],(string)$event['action'],(int)$event['sort_order']];
    }
    usort($rows,static function($a,$b) { return strcmp(json_encode($a),json_encode($b)); });
    return json_encode($rows,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);
}
function rd16_runtime(string $root, bool $checkThemes = true): array {
    ob_start();
    try {
