        require_once $root.'/config.php';
        foreach (['DIR_OPENCART','DIR_APPLICATION','DIR_SYSTEM','DIR_TEMPLATE','DIR_EXTENSION','DIR_CACHE'] as $key) if (!defined($key)) rd16_fail('runtime_constant_missing');
        if (rtrim(str_replace('\\','/',DIR_OPENCART),'/')!==$root || rtrim(str_replace('\\','/',DIR_APPLICATION),'/')!==$root.'/catalog' || rtrim(str_replace('\\','/',DIR_EXTENSION),'/')!==$root.'/extension' || rtrim(str_replace('\\','/',DIR_SYSTEM),'/')!==$root.'/system' || str_replace('\\','/',DIR_TEMPLATE)!==$root.'/catalog/view/template/' || defined('DIR_CATALOG')) rd16_fail('runtime_root_mapping_changed');
        if (DIR_CACHE.'template/'!==RD16_CACHE || !is_dir(RD16_CACHE) || is_link(rtrim(RD16_CACHE,'/')) || realpath(RD16_CACHE)!==rtrim(RD16_CACHE,'/')) rd16_fail('template_cache_mapping_changed');
        $facts=['root'=>$root,'php'=>PHP_VERSION,'cache'=>RD16_CACHE];
        if ($checkThemes) {
