            mysqli_report(MYSQLI_REPORT_OFF);
            $db=new mysqli(DB_HOSTNAME,DB_USERNAME,DB_PASSWORD,DB_DATABASE,(int)DB_PORT);
            if ($db->connect_errno || !$db->set_charset('utf8mb4')) rd16_fail('metadata_unavailable');
            foreach (['theme'=>['route','status'],'event'=>['code','trigger','action','sort_order','status'],'setting'=>['store_id','code','key','value','serialized'],'custom_field'=>['custom_field_id','type','value','validation','location','status','sort_order'],'custom_field_description'=>['custom_field_id','language_id','name'],'custom_field_customer_group'=>['custom_field_id','customer_group_id','required']] as $table=>$required) {
                $q=$db->query('SHOW COLUMNS FROM `'.DB_PREFIX.$table.'`');if(!$q)rd16_fail('metadata_schema_unavailable');$columns=[];
                while($row=$q->fetch_assoc())$columns[]=$row['Field'];$q->free();if(array_diff($required,$columns))rd16_fail('metadata_schema_changed');
            }
            if (!$db->query('START TRANSACTION READ ONLY')) rd16_fail('readonly_transaction_unavailable');
            $q=$db->query("SELECT `store_id`,`key`,LEFT(`value`,257) AS `value`,`serialized` FROM `".DB_PREFIX."setting` WHERE `key` IN ('config_theme','theme_default_directory') ORDER BY `store_id`,`key` LIMIT 1025");
            if(!$q)rd16_fail('theme_settings_unavailable');$settings=[];
            while($row=$q->fetch_assoc()){if(count($settings)>=1024)rd16_fail('theme_settings_cap');$settings[]=[(string)$row['store_id'],(string)$row['key'],$row['value'],(string)$row['serialized']];}$q->free();
            rd16_hook_templates($root,$settings,defined('DIR_MODIFICATION')?(string)DIR_MODIFICATION:null);
            $facts['theme_settings_sha256']=hash('sha256',json_encode($settings));
            $s=$db->prepare('SELECT COUNT(*) FROM `'.DB_PREFIX.'theme` WHERE `route` = ?');$route='';
            if(!$s || !$s->bind_param('s',$route))rd16_fail('theme_check_unavailable');
            foreach(['checkout/checkout','checkout/register','checkout/shipping_address','checkout/payment_address','common/header'] as $route){if(!$s->execute()||!$s->bind_result($count)||!$s->fetch())rd16_fail('theme_check_unavailable');if((int)$count!==0)rd16_fail('target_theme_override');$s->free_result();}$s->close();
            $q=$db->query('SELECT `code`,`trigger`,`action`,`sort_order`,`status` FROM `'.DB_PREFIX.'event` WHERE `status` = 1 LIMIT 1025');if(!$q)rd16_fail('event_check_unavailable');$events=[];
            while($row=$q->fetch_assoc()){if(count($events)>=1024)rd16_fail('event_cap');$events[]=$row;}$q->free();
            $normalized=rd17_events_normalize($events);
            if(hash('sha256',$normalized)!=='d6f18399a2bd4d7bc17a67fb9651a201fb126663e6f868f52494079e7131cf0f')rd16_fail('checkout_event_set_changed');
            $facts['checkout_events_sha256']=hash('sha256',$normalized);
            $q=$db->query("SELECT `store_id`,`key`,`value`,`serialized` FROM `".DB_PREFIX."setting` WHERE `key` LIKE 'payment%status' ORDER BY `store_id`,`key` LIMIT 1025");if(!$q)rd16_fail('payment_inventory_unavailable');$payments=[];$allowed=rd16_json('WyJiYW5rX3RyYW5zZmVyIiwiY2hlcXVlIiwiY29kIiwiZnJlZV9jaGVja291dCIsImh1dGtvIiwibW9ub19jaGFzdCIsInBpbnRhX25vdmFfcG9zaHRhX2NvZCIsInB1bWJfY3JlZGl0Il0=');
            while($row=$q->fetch_assoc()){
                if(count($payments)>=1024)rd16_fail('payment_inventory_cap');
                if(!preg_match('/^payment_([A-Za-z0-9_]+)_status$/D',(string)$row['key'],$match))continue;
                if((string)$row['serialized']!=='0'||!in_array((string)$row['value'],['0','1'],true))rd16_fail('payment_inventory_shape');
                if((string)$row['value']==='1'&&!in_array($match[1],$allowed,true))rd16_fail('unadmitted_payment_code');
                $payments[]=[(int)$row['store_id'],(string)$row['key'],(string)$row['value']];
            }$q->free();$facts['payment_inventory_sha256']=hash('sha256',json_encode($payments));
            // Check identities before requiring current application metadata code.
            $deps=rd16_dependencies();
            foreach(['system/library/booster_account_profile.php','system/library/booster_custom_field_guard.php'] as $path)if(!isset($deps[$path])||rd16_state(rd16_walk($root,$path))!==$deps[$path])rd16_fail('profile_registry_source_drift');
            require_once $root.'/system/library/booster_account_profile.php';
            $profile=new \Opencart\System\Library\BoosterAccountProfile(new Rd17ProfileMetadataDb($db));
            if(!$profile->active())rd16_fail('profile_registry_inactive');
            $facts['profile_registry_sha256']=hash('sha256',json_encode($profile->ids()));
            if(defined('DIR_MODIFICATION'))foreach(array_merge(array_column(rd16_targets(),'path'),array_keys(rd16_dependencies()))as$relative){$candidate=rtrim(str_replace('\\','/',DIR_MODIFICATION),'/').'/'.$relative;if(file_exists($candidate)||is_link($candidate))rd16_fail('generated_source_override');}
            if(!$db->rollback())rd16_fail('readonly_close_failed');$db->close();$facts['target_theme_overrides']=0;
        }
        ob_end_clean();return $facts;
    } catch(\Throwable $error) {
        while(ob_get_level())ob_end_clean();
        if($error instanceof \RuntimeException&&preg_match('/^[a-z_]+$/D',$error->getMessage()))throw $error;
        rd16_fail('runtime_admission_failed');
    }
}

function rd16_rollback_plan(string $root, string $backup, array $targets): array {
    $prefix=$root . '/_patch_backups/' . RD16_ID . '-';
    if (strpos($backup,$prefix)!==0 || !preg_match('/^[0-9]{8}T[0-9]{6}Z-[a-f0-9]{12}$/D',substr($backup,strlen($prefix))) || str_replace('\\','/',realpath($backup)?:'')!==$backup) rd16_fail('unsafe_backup_path');
    rd16_walk($root,substr($backup,strlen($root)+1));
    $manifest=$backup . '/manifest.json';
    if (rd16_state($manifest)==='absent') rd16_fail('backup_manifest_missing');
    $data=json_decode(file_get_contents($manifest),true);
    if (!is_array($data) || ($data['task']??'')!==RD16_ID || ($data['root']??'')!==$root || count($data['targets']??[])!==count($targets)) rd16_fail('backup_manifest_invalid');
    $plan=[];
    foreach ($targets as $i=>$contract) {
        $row=$data['targets'][$i];
        if (($row['path']??'')!==$contract['path'] || ($row['after']??'')!==$contract['after']) rd16_fail('backup_contract_mismatch');
        if (($row['before']??'')!==$contract['before']) rd16_fail('backup_before_contract_mismatch');
        $path=rd16_walk($root,$row['path']); $current=rd16_state($path);
        if ($current!==$row['before'] && $current!==$row['after']) rd16_fail('rollback_target_drift');
        if ($row['before']!=='absent') {
            $copy=$backup . '/original-' . $i;
            if (rd16_state($copy)!==$row['before']) rd16_fail('backup_hash_mismatch');

        }
        $row['current']=$current; $plan[]=$row;
    }
    return $plan;
}

$rd16_lock=null; $rd16_lockOwned=false; $rd16_stage=[];
try {
    if (PHP_SAPI!=='cli' || PHP_MAJOR_VERSION!==8) rd16_fail('php_cli_8_required');
    $root=realpath(getcwd());
    if (!is_string($root) || !is_dir($root . '/catalog')) rd16_fail('cwd_not_opencart');
    $root=str_replace('\\','/',$root);
    $stageRoot=str_replace('\\','/',realpath(__DIR__));
    if ($stageRoot===$root || strpos($stageRoot . '/',$root . '/')===0) rd16_fail('runner_must_be_private');
    if (stat($stageRoot)['dev'] !== stat($root)['dev']) rd16_fail('stage_filesystem_differs');
    $mode=$argv[1]??'';
    if (!in_array($mode,['--check','--apply'],true) && strpos($mode,'--rollback=')!==0 && strpos($mode,'--rollback-check=')!==0) rd16_fail('explicit_mode_required');
    $targets=rd16_targets();
    foreach ($targets as $target) rd16_walk($root,$target['path']);
    // Determine complete no-op before dependency admission: later tasks may have changed
    // a dependency or DS token. Never retouch a token on an otherwise complete no-op.
    $applied=true;
    foreach ($targets as $target) {
        $path=$root . '/' . $target['path'];
        if (rd16_state($path)!==$target['after']) $applied=false;
    }
    if ($applied && in_array($mode,['--check','--apply'],true)) { echo "already_applied=yes\n"; exit(0); }
    // Shared with the installed profile bridge: serialize overlapping Twig writers.
    $rd16_lock=$stageRoot . '/RD-17-WP1A_profile-receiver_20261026.lock';
    rd16_write_new($rd16_lock,(string)getmypid());
    $rd16_lockOwned=true;
    $runtime=rd16_runtime($root,strpos($mode,'--rollback')!==0);
    if (strpos($mode,'--rollback')===0) {
        $backup=substr($mode,strpos($mode,'=')+1);
        $plan=rd16_rollback_plan($root,$backup,$targets);
        echo 'backup=' . $backup . "\nrollback_preflight=ok\n";
        if (strpos($mode,'--rollback-check=')===0) { echo "done=ok\n"; }
        else {
            // Prepare/lint every restore candidate before any target is modified.
            foreach ($plan as $i=>$row) {
                if ($row['current']===$row['before'] || $row['before']==='absent') continue;
                $candidate=$stageRoot . '/RD16-restore-' . bin2hex(random_bytes(6)) . (substr($row['path'],-4)==='.php'?'.php':'.tmp');
                rd16_write_new($candidate,file_get_contents($backup . '/original-' . $i));
                rd16_permissions($candidate,$row); rd16_lint($candidate); $rd16_stage[$i]=$candidate;
            }
            // Recheck all live/backup states immediately before the first rollback write.
            $secondPlan=rd16_rollback_plan($root,$backup,$targets);
            foreach ($secondPlan as $i=>$row) {
                if ($row['current']!==$plan[$i]['current']) rd16_fail('rollback_state_changed_during_preflight');
                if (isset($rd16_stage[$i]) && rd16_state($rd16_stage[$i])!==$row['before']) rd16_fail('restore_candidate_hash_changed');
            }
            $plan=$secondPlan;
            // Restore the installed bridge view before removing the two new UI assets.
            foreach ([2,1,0] as $i) {
                $row=$plan[$i];
                if ($row['current']===$row['before']) continue;
                $path=$root . '/' . $row['path'];
                if ($row['before']==='absent') { if (!unlink($path)) rd16_fail('created_target_remove_failed'); }
                elseif (!rename($rd16_stage[$i],$path)) rd16_fail('restore_rename_failed');
                if (rd16_state($path)!==$row['before']) rd16_fail('restore_hash_failed');
            }
            echo "rollback=ok\nchanged_files=" . count(array_filter($plan,static function($row){return $row['current']!==$row['before'];})) . "\n";
            if (!unlink(__FILE__)) rd16_fail('self_delete_failed');
            echo "self_deleted=yes\ndone=ok\n";
        }
    } else {
        $rows=[]; $payloads=[];
        foreach ($targets as $i=>$target) {
            $path=$root . '/' . $target['path']; $actual=rd16_state($path);
            if ($actual!==$target['before']) rd16_fail('target_before_mismatch');
            $new=base64_decode($target['payload'],true);
            if (!is_string($new) || hash('sha256',$new)!==$target['after']) rd16_fail('payload_hash_mismatch');
            $rows[]=['path'=>$target['path'],'before'=>$actual,'after'=>$target['after'],'mode'=>$actual==='absent'?0644:(fileperms($path)&0777),'uid'=>$actual==='absent'?null:fileowner($path),'gid'=>$actual==='absent'?null:filegroup($path)];
            $payloads[$i]=$new;
        }
        foreach (rd16_dependencies() as $relative=>$expected) if (rd16_state(rd16_walk($root,$relative))!==$expected) rd16_fail('dependency_source_drift');
        $admission=hash('sha256',json_encode(['runtime'=>$runtime,'targets'=>$rows,'dependencies'=>rd16_dependencies()]));
        foreach ($rows as $i=>$row) {
            $candidate=$stageRoot . '/RD16-candidate-' . bin2hex(random_bytes(6)) . (substr($row['path'],-4)==='.php'?'.php':'.tmp');
            rd16_write_new($candidate,$payloads[$i]); $rd16_stage[$i]=$candidate; rd16_lint($candidate);
        }
        echo 'admission_sha256=' . $admission . "\nsyntax_gate=ok\n";
        if ($mode==='--check') { echo "production_writes=0\nbackup=none\ndone=ok\n"; }
        else {
            if (($argv[2]??'')!=='--admission=' . $admission) rd16_fail('admission_changed_or_missing');
            $backupBase=rd16_walk($root,'_patch_backups');
            if (!file_exists($backupBase) && !mkdir($backupBase,0700)) rd16_fail('backup_root_create_failed');
            if (!is_dir($backupBase)) rd16_fail('backup_root_invalid');
            if (stat($backupBase)['dev'] !== stat($root)['dev']) rd16_fail('backup_filesystem_differs');
            $backup=$backupBase . '/' . RD16_ID . '-' . gmdate('Ymd\THis\Z') . '-' . bin2hex(random_bytes(6));
            if (!mkdir($backup,0700)) rd16_fail('backup_create_failed');
            foreach ($rows as $i=>$row) {
                if ($row['before']==='absent') continue;
                $body=file_get_contents($root . '/' . $row['path']);
                if (hash('sha256',$body)!==$row['before']) rd16_fail('source_changed_before_backup');
                rd16_write_new($backup . '/original-' . $i,$body);
                if (rd16_state($backup . '/original-' . $i)!==$row['before']) rd16_fail('backup_hash_failed');
            }
            rd16_write_new($backup . '/manifest.json',json_encode(['task'=>RD16_ID,'root'=>$root,'targets'=>$rows],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));
            echo 'backup=' . $backup . "\n";
            foreach ($rows as $i=>$row) if (rd16_state($root . '/' . $row['path'])!==$row['before']) rd16_fail('source_changed_before_write');
            foreach (rd16_dependencies() as $relative=>$expected) if (rd16_state(rd16_walk($root,$relative))!==$expected) rd16_fail('dependency_changed_before_write');
            foreach ($rows as $i=>$row) rd16_permissions($rd16_stage[$i],$row);
            $changed=[];
            try {
                // Both new presentation assets first; the only existing caller view last.
                foreach ([0,1,2] as $i) {
                    $row=$rows[$i];
                    $path=$root . '/' . $row['path'];
                    if (!rename($rd16_stage[$i],$path)) rd16_fail('target_atomic_rename_failed');
                    $changed[]=$i;
                    if (rd16_state($path)!==$row['after']) rd16_fail('target_post_hash_failed');
                    rd16_lint($path);
                }
            } catch (Throwable $writeError) {
                // Known partial writes only; preflight every target/backup before repair.
                $restore=rd16_rollback_plan($root,$backup,$targets);
                foreach (array_reverse($changed) as $i) {
                    $row=$restore[$i]; $path=$root . '/' . $row['path'];
                    if ($row['before']==='absent') { if (!unlink($path)) rd16_fail('automatic_restore_failed'); }
                    else {
                        $candidate=$stageRoot . '/RD16-auto-restore-' . $i . '-' . bin2hex(random_bytes(6));
                        rd16_write_new($candidate,file_get_contents($backup . '/original-' . $i));
                        rd16_permissions($candidate,$row);
                        if (!rename($candidate,$path) || rd16_state($path)!==$row['before']) rd16_fail('automatic_restore_failed');
                    }
                }
                echo "automatic_restore=ok\n";
                throw $writeError;
            }
            foreach ($rows as $i=>$row) echo 'target=' . $row['path'] . ' sha256_before=' . $row['before'] . ' sha256_after=' . $row['after'] . ' backup=' . ($row['before']==='absent'?'none':$backup . '/original-' . $i) . "\n";
            echo "changed_files=3\n";
            if (!unlink(__FILE__)) rd16_fail('self_delete_failed');
            echo "self_deleted=yes\ndone=ok\n";
        }
    }
} catch (Throwable $error) {
    echo 'error=' . (($error instanceof RuntimeException && preg_match('/^[a-z_]+$/D',$error->getMessage()))?$error->getMessage():'operation_failed') . "\n";
    $rd16_error=true;
} finally {
    foreach ($rd16_stage as $candidate) if (is_file($candidate) && !is_link($candidate)) unlink($candidate);
    if ($rd16_lockOwned && $rd16_lock && is_file($rd16_lock) && !is_link($rd16_lock)) unlink($rd16_lock);
}
if (!empty($rd16_error)) exit(1);
